/**
 * TxScript Types
 *
 * Types for the TxScript-like (Rossum-inspired) formula evaluation system.
 * The tx capability object mediates all reads, writes, and side effects.
 *
 * @module TxScript
 */

// ═══════════════════════════════════════════════════════════════════════════════
// TX RESULT TYPES
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Notification levels for formula messages
 */
export type TxNotificationLevel = "info" | "warning" | "error";

/**
 * Notification generated by tx.addMessage()
 */
export interface TxNotification {
  level: TxNotificationLevel;
  message: string;
  fieldPath?: string; // e.g., "items[2].sku"
}

/**
 * Full result of a tx execution containing all mutations
 */
export interface TxResult {
  /** The computed result value for this formula field (set via tx.setResult) */
  result: unknown;

  /** Header field changes (field name -> value) via tx.setField */
  fieldChanges: Record<string, unknown>;

  /** Line item field changes (collection -> index -> field -> value) via tx.setLineField */
  lineFieldChanges: Record<string, Record<number, Record<string, unknown>>>;

  /** Notifications generated during execution via tx.addMessage */
  messages: TxNotification[];

  /** Execution metadata for monitoring/debugging */
  metadata: TxExecutionMetadata;
}

/**
 * Execution metadata for monitoring and debugging
 */
export interface TxExecutionMetadata {
  httpCallCount: number;
  readCount: number;
  writeCount: number;
  datasetLookupCount: number;
  executionTimeMs?: number;
}

// ═══════════════════════════════════════════════════════════════════════════════
// HTTP TYPES
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * HTTP request options for tx.http.request()
 */
export interface TxHttpOptions {
  method?: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
  url: string;
  headers?: Record<string, string>;
  body?: unknown;
  timeoutMs?: number;
}

/**
 * HTTP response from tx.http.request()
 */
export interface TxHttpResponse {
  status: number;
  ok: boolean;
  body: unknown;
  bodyText: string;
  headers: Record<string, string>;
}

// ═══════════════════════════════════════════════════════════════════════════════
// CONTEXT TYPES
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * File metadata available in formula context
 */
export interface TxFileMetadata {
  id: string;
  fileName: string;
  uploadDate: string; // ISO date
  fileType: string; // MIME type
  status: string; // extractionStatus
}

/**
 * Full context available to formula execution
 */
export interface TxFormulaContext {
  header: Record<string, unknown>;
  lineItems: Record<string, Record<string, unknown>[]>;
  file: TxFileMetadata;
}

// ═══════════════════════════════════════════════════════════════════════════════
// TX INTERFACE
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Utility methods available on tx.utils
 */
export interface TxUtils {
  /** Check if value is a non-empty string */
  isNonEmptyString(s: unknown): s is string;

  /** Parse number from string or number */
  parseNumber(s: unknown): number | null;

  /** Check if value is nullish (null or undefined) */
  isNullish(value: unknown): value is null | undefined;

  /** Format currency (simple version) */
  formatCurrency(amount: number, currency?: string): string;
}

/**
 * Dataset lookup methods available on tx.dataset
 */
export interface TxDatasetMethods {
  /** Get all rows from a dataset (case-insensitive name matching) */
  getAll(name: string): Record<string, unknown>[];

  /** Find first matching row in a dataset */
  find(
    name: string,
    predicate: (row: Record<string, unknown>) => boolean
  ): Record<string, unknown> | null;

  /** Find all matching rows in a dataset */
  filter(
    name: string,
    predicate: (row: Record<string, unknown>) => boolean
  ): Array<Record<string, unknown>>;

  /** Lookup row by field value (case-insensitive field names) */
  lookup(
    name: string,
    field: string,
    value: unknown
  ): Record<string, unknown> | null;
}

/**
 * HTTP methods available on tx.http
 */
export interface TxHttpMethods {
  /** Make an HTTP request to an external API */
  request(opts: TxHttpOptions): Promise<TxHttpResponse>;
}

/**
 * Full TX capability interface (for documentation/typing purposes)
 *
 * This represents the tx object passed to formula code:
 * - Read header/line item data
 * - Set results and field values
 * - Add notifications
 * - Lookup datasets
 * - Make HTTP requests
 */
export interface TxCapabilityInterface {
  // Read operations
  getField(name: string): unknown;
  getFields(names: string[]): Record<string, unknown>;
  getLineItem(collection: string, index: number): Record<string, unknown>;
  getCurrentLineItem(): Record<string, unknown> | null;
  getLineItems(collection: string): Array<Record<string, unknown>>;
  getContext(): Readonly<TxFormulaContext>;
  getCurrentCollection(): string | null;
  getCurrentIndex(): number | null;

  // Write operations
  setResult(value: unknown): void;
  setField(name: string, value: unknown): void;
  setFields(fields: Record<string, unknown>): void;
  setLineField(
    collection: string,
    index: number,
    name: string,
    value: unknown
  ): void;
  setCurrentLineField(name: string, value: unknown): void;

  // Messaging
  addMessage(
    text: string,
    opts?: { level?: TxNotificationLevel; field?: string }
  ): void;

  // Logging
  log(
    level: "debug" | "info" | "warn" | "error",
    message: string,
    meta?: Record<string, unknown>
  ): void;

  // Utilities
  utils: TxUtils;

  // Dataset access
  dataset: TxDatasetMethods;

  // HTTP access
  http: TxHttpMethods;
}

// ═══════════════════════════════════════════════════════════════════════════════
// LIMITS AND CONFIG
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Default limits for tx execution
 */
export const TX_DEFAULT_LIMITS = {
  maxHttpCalls: 10,
  httpTimeoutMs: 300000, // 5 minutes
  executionTimeoutMs: 300000, // 5 minutes
  maxResponseBodyBytes: 1024 * 1024, // 1MB
} as const;

export type TxLimits = typeof TX_DEFAULT_LIMITS;
